package dk.stream.android;
import org.json.*;
import java.util.*;
import java.util.regex.*;
import okhttp3.HttpUrl;
/** Public Saavn.dev song metadata; only API-provided HTTP media addresses are used. */
final class SaavnSong {
 final String id,title,artist,album,image,stream;final long duration;
 SaavnSong(String id,String title,String artist,String album,String image,String stream,long duration){this.id=id;this.title=title;this.artist=artist;this.album=album;this.image=image;this.stream=stream;this.duration=Math.max(0,duration);}
 static SaavnSong parse(JSONObject value)throws JSONException{String id=value.getString("id");if(!id.matches("[A-Za-z0-9_-]{1,128}"))throw new JSONException("Invalid song ID");String title=text(value.optString("name",value.optString("title","")));if(title.isEmpty())title="Ukendt titel";List<String> names=new ArrayList<>();JSONObject artists=value.optJSONObject("artists");JSONArray primary=artists==null?null:artists.optJSONArray("primary");if(primary!=null)for(int i=0;i<primary.length();i++){JSONObject entry=primary.optJSONObject(i);if(entry!=null&&!entry.optString("name").isEmpty())names.add(text(entry.optString("name")));}String artist=names.isEmpty()?text(value.optString("primaryArtists",value.optString("primary_artists",""))):join(names);JSONObject album=value.optJSONObject("album");return new SaavnSong(id,title,artist,album==null?"":text(album.optString("name")),best(value.optJSONArray("image")),best(value.optJSONArray("downloadUrl")),value.optLong("duration",0));}
 static String best(JSONArray items){String result="";int rank=-1;if(items!=null)for(int i=0;i<items.length();i++){JSONObject item=items.optJSONObject(i);if(item==null)continue;String url=item.optString("url",item.optString("link",""));HttpUrl parsed=HttpUrl.parse(url);if(parsed==null)continue;Matcher number=Pattern.compile("[0-9]+").matcher(item.optString("quality"));int score=0;try{if(number.find())score=Integer.parseInt(number.group());}catch(NumberFormatException ignored){}if(score>rank){rank=score;result=parsed.toString();}}return result;}
 private static String join(List<String> names){StringBuilder result=new StringBuilder();for(String name:names){if(result.length()>0)result.append(", ");result.append(name);}return result.toString();}
 static String text(String input){String value=input.replace("&amp;","&").replace("&quot;","\"").replace("&apos;","'").replace("&lt;","<").replace("&gt;",">").replace("&nbsp;"," ");Matcher match=Pattern.compile("&#(x[0-9a-fA-F]+|[0-9]+);").matcher(value);StringBuffer decoded=new StringBuffer();while(match.find()){String code=match.group(1);String replacement=match.group();try{int point=Integer.parseInt(code.startsWith("x")?code.substring(1):code,code.startsWith("x")?16:10);if(Character.isValidCodePoint(point))replacement=new String(Character.toChars(point));}catch(Exception ignored){}match.appendReplacement(decoded,Matcher.quoteReplacement(replacement));}match.appendTail(decoded);return decoded.toString().trim();}
 JSONObject json()throws JSONException{JSONObject artists=new JSONObject().put("primary",new JSONArray().put(new JSONObject().put("name",artist)));JSONObject result=new JSONObject().put("id",id).put("name",title).put("artists",artists).put("album",new JSONObject().put("name",album)).put("duration",duration);result.put("image",new JSONArray().put(new JSONObject().put("quality","500x500").put("url",image)));result.put("downloadUrl",new JSONArray().put(new JSONObject().put("quality","320kbps").put("url",stream)));return result;}
}
